<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Mount Fuji &amp; Chureito Pagoda - Low-Poly Dusk Diorama</title>
  <style>
    :root {
      color-scheme: dark;
    }
    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }
    html, body {
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: #17152b;
      font-family: "Segoe UI", system-ui, -apple-system, sans-serif;
    }
    canvas {
      display: block;
      width: 100%;
      height: 100%;
    }
    #hud {
      position: fixed;
      left: 20px;
      bottom: 18px;
      pointer-events: none;
      color: rgba(255, 238, 230, 0.82);
      text-shadow: 0 2px 10px rgba(10, 8, 22, 0.85);
      letter-spacing: 0.08em;
      font-size: 12px;
      line-height: 1.45;
      user-select: none;
    }
    #hud strong {
      display: block;
      font-size: 14px;
      font-weight: 600;
      color: rgba(255, 245, 238, 0.96);
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }
  </style>
  <script type="importmap">
    {
      "imports": {
        "three": "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js",
        "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.170.0/examples/jsm/"
      }
    }
  </script>
</head>
<body>
  <div id="hud">
    <strong>Arakurayama Sengen Park &middot; Dusk</strong>
    Chureito Pagoda &amp; Mount Fuji &middot; Drag to orbit, scroll to zoom
  </div>

  <script type="module">
    import * as THREE from "three";
    import { OrbitControls } from "three/addons/controls/OrbitControls.js";

    // Deterministic PRNG so the procedural low-poly composition is identical on every load
    function createSeededRandom(seedValue) {
      let state = seedValue >>> 0;
      return function nextRandom() {
        state = (1664525 * state + 1013904223) >>> 0;
        return state / 4294967296;
      };
    }

    const rng = createSeededRandom(20261031);
    const randRange = (min, max) => min + (max - min) * rng();

    // Scene, atmospheric dusk fog, and renderer setup
    const scene = new THREE.Scene();
    scene.fog = new THREE.FogExp2(0xd87b74, 0.00155);

    const camera = new THREE.PerspectiveCamera(
      39,
      window.innerWidth / window.innerHeight,
      0.5,
      950
    );

    // Classic Arakurayama viewing deck vantage point:
    // Elevated slightly above the pagoda terrace, looking past the 5-tier red Chureito Pagoda
    // on the right and blooming sakura in the foreground toward Mount Fuji on the center-left.
    const baseCameraPos = new THREE.Vector3(3.2, 18.8, 42.0);
    const baseLookTarget = new THREE.Vector3(-4.2, 14.2, -38.0);
    camera.position.copy(baseCameraPos);

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      powerPreference: "high-performance"
    });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.12;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    document.body.appendChild(renderer.domElement);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.target.copy(baseLookTarget);
    controls.enableDamping = true;
    controls.dampingFactor = 0.05;
    controls.maxPolarAngle = Math.PI * 0.52;
    controls.minDistance = 12;
    controls.maxDistance = 150;
    controls.update();

    let userInteracting = false;
    let lastInteractionTime = -100;
    controls.addEventListener("start", () => {
      userInteracting = true;
    });
    controls.addEventListener("end", () => {
      userInteracting = false;
      lastInteractionTime = performance.now() * 0.001;
    });

